#include <stdio.h>

int main() {
    int a, b;
    /* scanf 读入时，变量前必须加 &（取地址符） */
    scanf("%d %d", &a, &b);
    printf("%d\n", a + b);
    return 0;
}

#include <stdio.h>

int main() {
    double r;
    scanf("%lf", &r);
    const double pi = 3.14159;
    /* %.2f 表示保留 2 位小数 */
    printf("%.2f\n", pi * r * r);
    return 0;
}

#include <stdio.h>

int main() {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);
    /* 先假设 a 最大，再依次挑战它 */
    int max = a;
    if (b > max) max = b;
    if (c > max) max = c;
    printf("%d\n", max);
    return 0;
}

