#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);
    /* 累加变量一定要初始化为 0 */
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += i;
    }
    printf("%d\n", sum);
    return 0;
}

