#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);
    /* n % 2 == 0 表示能被 2 整除 */
    if (n % 2 == 0) {
        printf("even\n");
    } else {
        printf("odd\n");
    }
    return 0;
}
